// Normal strips: each band row is [xa, ya, xb, yb] (its two edges on one cross-section of the ribbon); the flags taper
// the band's head/tail to a point (the band appears/vanishes as the ribbon twists).
function ribbonN(ctx, bands, { lw = 2.2, ink = RIB_INK } = {}) {
  const polys = bands.map(([cls, rows, th, tt]) => {
    const A = rows.map((r) => [r[0], r[1]]), B = rows.map((r) => [r[2], r[3]]);
    const mid = (r) => [(r[0] + r[2]) / 2, (r[1] + r[3]) / 2];
    const ext = (r, q) => { const m = mid(r), n = mid(q); return [m[0] + (m[0] - n[0]) * 0.6, m[1] + (m[1] - n[1]) * 0.6]; };
    const head = th && rows.length > 1 ? [ext(rows[0], rows[1])] : [], tail = tt && rows.length > 1 ? [ext(rows[rows.length - 1], rows[rows.length - 2])] : [];
    const L = sampleCurve([...head, ...A, ...tail], 6), R = sampleCurve([...head, ...B, ...tail], 6);
    return [cls, L, R];
  });
  for (const [cls, L, R] of polys) { ctx.beginPath(); poly(ctx, [...L, ...R.slice().reverse()]); ctx.fillStyle = ink[cls] || cls; ctx.fill(); }
  // ink only the long edges (open ends meet the next ribbon piece without a seam)
  ctx.lineJoin = "round"; ctx.lineCap = "round"; ctx.strokeStyle = HC.line; ctx.lineWidth = lw;
  for (const [, L, R] of polys) for (const E of [L, R]) { ctx.beginPath(); poly(ctx, E, false); ctx.stroke(); }
}
// @@END STRIPS
function ribbons(ctx) {
  ribbonN(ctx, RIB_STRIPS.nL);
  ribbonN(ctx, RIB_STRIPS.nR);
}

