function circlesPath(ctx, C, grow = 0) {
  ctx.beginPath();
  for (const [x, y, r] of C) { const R = Math.max(0.5, r + grow); ctx.moveTo(x + R, y); ctx.arc(x, y, R, 0, TAU); }
}
function softCircles(ctx, C, col, soft) {
  const n = parseInt(col.slice(1), 16), rgb = `${n >> 16},${(n >> 8) & 255},${n & 255}`;
  for (const [x, y, r] of C) {
    const R = r + soft / 2, r0 = Math.max(0, r - soft / 2);
    const g = ctx.createRadialGradient(x, y, r0, x, y, R);
    g.addColorStop(0, `rgba(${rgb},1)`); g.addColorStop(1, `rgba(${rgb},0)`);
    ctx.fillStyle = g; ctx.beginPath(); ctx.arc(x, y, R, 0, TAU); ctx.fill();
  }
}
function cloud(ctx, cl) {
  const L = cl.layers;
  for (const ly of L) {
    ctx.save();
    if (ly.clip !== undefined) { circlesPath(ctx, L[ly.clip].c); ctx.clip(); }
    if (ly.soft) softCircles(ctx, ly.c, ly.col, ly.soft);
    else {
      if (ly.line) { circlesPath(ctx, ly.c, ly.line); ctx.fillStyle = HC.line; ctx.fill(); }
      circlesPath(ctx, ly.c);
      if (ly.grad) {
        const [x0, y0, x1, y1, stops] = ly.grad, g = ctx.createLinearGradient(x0, y0, x1, y1);
        for (const [u, c] of stops) g.addColorStop(u, c);
        ctx.fillStyle = g;
      } else ctx.fillStyle = ly.col;
      ctx.fill();
    }
    ctx.restore();
  }
}
