  ctx.save(); ctx.beginPath(); ctx.rect(WORLD_X0, -20, -WORLD_X0 + 1, PAGE_H + 40); ctx.rect(PAGE_W - 1, -20, WORLD_X1 - PAGE_W + 1, PAGE_H + 40); ctx.clip();
