// ---------- flat-faced objects (boxes, panels) ----------
// Items ["q", ink, [x, y, …], [tape quads]?]: a flat face from its measured corners, filled with its sampled ink and
// inked; tape squares on top in the tape ink.
const TAPE = "#45343f";
function flatPath(ctx, P) { ctx.beginPath(); ctx.moveTo(P[0], P[1]); for (let i = 2; i < P.length; i += 2) ctx.lineTo(P[i], P[i + 1]); ctx.closePath(); }
function faces(ctx, list, lw = 2.8) {
  ctx.save(); ctx.lineJoin = "round"; ctx.lineCap = "round"; ctx.strokeStyle = HC.line; ctx.lineWidth = lw;
  for (const it of list) {
    flatPath(ctx, it[2]); ctx.fillStyle = it[1]; ctx.fill(); ctx.stroke();
    if (it[3]) for (const t of it[3]) { flatPath(ctx, t); ctx.fillStyle = TAPE; ctx.fill(); ctx.lineWidth = lw * 0.6; ctx.stroke(); ctx.lineWidth = lw; }
  }
  ctx.restore();
}
