// ---------- composition ----------
export function drawHippieWorld(ctx, opts = {}) {
  const { headline: withHeadline = true, nav: withNav = true, scene: withScene = true } = opts;
  backdrop(ctx);
  if (withScene) { scene(ctx); designer(ctx); desk(ctx); mug(ctx); cablesFront(ctx); }
  if (withHeadline) headline(ctx);
  if (withNav) nav(ctx);
}

// ---------- print finish ----------
// The source page is a soft, grainy print: every cached page/layer is softened by a small gaussian (0.6 page px,
// measured on its ink edges) and given a fixed multiplicative grain (σ ≈ 2.4 % of the ink, ~1.5 px blobs; matched
// to the source's extra texture on flat light inks). Deterministic: the grain is a seeded tile.
let grainTile = null;
function grainField() {
  if (grainTile) return grainTile;
  const N = 509, r = rng(4242), f = new Float32Array(N * N);
  for (let i = 0; i < f.length; i++) f[i] = (r() + r() + r() - 1.5) * 2;
  // soften to ~1.5 px blobs (box 3x3), then renormalise
  const g = new Float32Array(N * N); let ss = 0;
  for (let y = 0; y < N; y++) for (let x = 0; x < N; x++) {
    let a = 0; for (let j = -1; j <= 1; j++) for (let i = -1; i <= 1; i++) a += f[((y + j + N) % N) * N + ((x + i + N) % N)] * (i === 0 && j === 0 ? 2 : 1);
    g[y * N + x] = a / 10; ss += (a / 10) ** 2;
  }
  const sd = Math.sqrt(ss / g.length); for (let i = 0; i < g.length; i++) g[i] /= sd;
  return (grainTile = { N, g });
}
// separable gaussian on RGBA bytes, clamped at the borders (so the page edges do not darken)
function blurClamp(d, w, h, sigma) {
  const r = Math.max(1, Math.ceil(sigma * 3)), k = new Float32Array(2 * r + 1);
  let sum = 0; for (let i = -r; i <= r; i++) { k[i + r] = Math.exp(-0.5 * (i * i) / (sigma * sigma)); sum += k[i + r]; }
  for (let i = 0; i < k.length; i++) k[i] /= sum;
  const tmp = new Float32Array(w * h * 4);
  for (let y = 0; y < h; y++) {
    const row = y * w;
    for (let x = 0; x < w; x++) {
      let a0 = 0, a1 = 0, a2 = 0, a3 = 0;
      for (let i = -r; i <= r; i++) { const xx = x + i < 0 ? 0 : x + i >= w ? w - 1 : x + i, j = (row + xx) * 4, kk = k[i + r]; a0 += d[j] * kk; a1 += d[j + 1] * kk; a2 += d[j + 2] * kk; a3 += d[j + 3] * kk; }
      const o = (row + x) * 4; tmp[o] = a0; tmp[o + 1] = a1; tmp[o + 2] = a2; tmp[o + 3] = a3;
    }
  }
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
    let a0 = 0, a1 = 0, a2 = 0, a3 = 0;
    for (let i = -r; i <= r; i++) { const yy = y + i < 0 ? 0 : y + i >= h ? h - 1 : y + i, j = (yy * w + x) * 4, kk = k[i + r]; a0 += tmp[j] * kk; a1 += tmp[j + 1] * kk; a2 += tmp[j + 2] * kk; a3 += tmp[j + 3] * kk; }
    const o = (y * w + x) * 4; d[o] = a0; d[o + 1] = a1; d[o + 2] = a2; d[o + 3] = a3;
  }
}
function finish(c, scale = 1, grain = 0.024, soft = 0.6) {
  const g = c.getContext("2d", { willReadFrequently: true });
  const id = g.getImageData(0, 0, c.width, c.height), d = id.data;
  if (soft > 0) blurClamp(d, c.width, c.height, soft * scale);
  if (grain > 0) {
    const { N, g: F } = grainField(), inv = 1 / Math.max(1, scale * 0.8);
    for (let y = 0; y < c.height; y++) {
      const yy = (Math.floor(y * inv) % N) * N;
      for (let x = 0; x < c.width; x++) {
        const k = 1 + grain * F[yy + (Math.floor(x * inv) % N)], o = (y * c.width + x) * 4;
        d[o] = d[o] * k; d[o + 1] = d[o + 1] * k; d[o + 2] = d[o + 2] * k;
      }
    }
  }
  g.putImageData(id, 0, 0);
  return c;
}

const cache = new Map();
function canvasOf(key, w, h, paint, fin = null) {
  let c = cache.get(key);
  if (!c) {
    c = document.createElement("canvas"); c.width = w; c.height = h;
    paint(c.getContext("2d", { willReadFrequently: !!fin }));
    if (fin) finish(c, ...fin);
    cache.set(key, c);
  }
  return c;
}
export function releaseHippie() { cache.clear(); grainTile = null; }

// The full colour page, 2206 x 946 (x scale for supersampling; default 1).
export function hippiePageCanvas({ headline = true, nav = true, scale = 1 } = {}) {
  return canvasOf(`page:${headline}:${nav}:${scale}`, Math.round(PAGE_W * scale), Math.round(PAGE_H * scale), (g) => {
    g.scale(scale, scale);
    g.save(); g.beginPath(); g.rect(0, 0, PAGE_W, PAGE_H); g.clip();
    drawHippieWorld(g, { headline, nav });
    g.restore();
  }, [scale]);
}
// Individual layers, each 2206 x 946 in page coordinates (transparent where empty):
//   "illustration"  the whole page without headline and nav (opaque)
//   "backdrop"      sky, stars, ribbons and clouds only (opaque)
//   "scene"         everything in front of the backdrop: boxes, gear, plants, the sign, the designer (transparent)
//   "designer"      the designer, his laptop and the desk (transparent)
//   "headline"      the lettering with its extrusion (transparent)
//   "nav"           brand mark + the four nav pills (transparent)
export function hippieLayer(name, scale = 1) {
  const w = Math.round(PAGE_W * scale), h = Math.round(PAGE_H * scale);
  return canvasOf(`layer:${name}:${scale}`, w, h, (g) => {
    g.scale(scale, scale);
    if (name === "illustration") drawHippieWorld(g, { headline: false, nav: false });
    else if (name === "backdrop") backdrop(g);
    else if (name === "scene") { scene(g); designer(g); desk(g); mug(g); cablesFront(g); }
    else if (name === "designer") { designer(g); desk(g); }
    else if (name === "headline") headline(g);
    else if (name === "nav") nav(g);
    else throw new Error(`hippieLayer: unknown layer ${name}`);
  }, [scale]);
}

// The page pre-shrunk to width w (halving steps, so thin lines stay clean) — for the laptop screen in the morning
// room (117.5–129 s, where the page is ~755 px wide). Aspect 2206:946.
export function hippiePageSmall(w, { headline = true, nav = true } = {}) {
  return canvasOf(`small:${w}:${headline}:${nav}`, Math.round(w), Math.round((w * PAGE_H) / PAGE_W), (g) => {
    let src = hippiePageCanvas({ headline, nav }), cw = src.width, ch = src.height;
    while (cw / 2 > w * 1.4) {
      const c = document.createElement("canvas"); c.width = Math.round(cw / 2); c.height = Math.round(ch / 2);
      const cg = c.getContext("2d"); cg.imageSmoothingQuality = "high"; cg.drawImage(src, 0, 0, c.width, c.height);
      src = c; cw = c.width; ch = c.height;
    }
    g.imageSmoothingQuality = "high";
    g.drawImage(src, 0, 0, g.canvas.width, g.canvas.height);
  });
}

// Where the colour owl perches on the page (not drawn here): the lid of the top yellow box, between its feet, at
// 117.04–117.52 s. At 117.4 s the owl covers x 1951–2108, y 65–244.
export const OWL_PERCH = { x: 2022, y: 236 };

// The colour page's camera in the source as it arrives (s26): page → frame similarity x' = s·x + tx, y' = s·y + ty.
// Settles to identity at 114.9 s.
export const PAGE_ARRIVAL = [
  [112.7, 0.8219, 166.7, 100.5], [112.9, 0.8288, 165.8, 101.5], [113.1, 0.8505, 147.1, 91.6], [113.3, 0.8869, 110.1, 72.4],
  [113.45, 0.9211, 70.6, 52.0], [113.6, 0.9385, 55.2, 39.3], [113.8, 0.9616, 35.8, 25.7], [114.05, 0.9792, 18.9, 13.7],
  [114.3, 0.9912, 9.0, 6.7], [114.5, 0.9953, 5.1, 2.8], [114.7, 0.9992, 0.8, 0.4], [114.9, 1, 0, 0],
];
export function pageArrival(t) {
  const A = PAGE_ARRIVAL;
  if (t <= A[0][0]) return { s: A[0][1], tx: A[0][2], ty: A[0][3] };
  for (let i = 1; i < A.length; i++) if (t <= A[i][0]) {
    const [t0, s0, x0, y0] = A[i - 1], [t1, s1, x1, y1] = A[i], u = (t - t0) / (t1 - t0);
    return { s: s0 + (s1 - s0) * u, tx: x0 + (x1 - x0) * u, ty: y0 + (y1 - y0) * u };
  }
  return { s: 1, tx: 0, ty: 0 };
}

// ---------- the header banner ----------
// The colour strip sits in the sōko page's HEADER slot (sites.js), page coordinates of the full-frame B&W page.
// Every shot draws it with ctx.drawImage(hippieBannerCanvas(), HEADER.x, HEADER.y, HEADER.w, HEADER.h).
export const BANNER = { x: HEADER.x, y: HEADER.y, w: HEADER.w, h: HEADER.h };
// The strip's artwork is the colour page itself, scaled and cropped: B&W page = S · colour + T.
export const BANNER_MAP = { sx: 0.6986, sy: 0.6879, tx: 335.2, ty: 11.3 };
const BANNER_SS = 2;
export function hippieBannerCanvas() {
  const { x, y, w, h } = BANNER, M = BANNER_MAP;
  return canvasOf("banner", Math.round(w * BANNER_SS), Math.round(h * BANNER_SS), (g) => {
    g.scale(BANNER_SS, BANNER_SS);
    g.translate(-x, -y);
    g.translate(M.tx, M.ty); g.scale(M.sx, M.sy);
    drawHippieWorld(g, { headline: true, nav: false });
  }, [BANNER_SS * M.sx]);
}
// Draw the strip into its slot, in page coordinates, under the caller's transform.
export function drawHippieBanner(ctx, alpha = 1) {
  const c = hippieBannerCanvas();
  ctx.save(); ctx.globalAlpha *= alpha;
  ctx.drawImage(c, BANNER.x, BANNER.y, BANNER.w, BANNER.h);
  ctx.restore();
}
